package com.agacostays.billing.validation;import com.agacostays.billing.entity.Bill;import com.agacostays.billing.exception.BusinessRuleException;import org.springframework.stereotype.Component;import java.math.BigDecimal;@Component public class BillingValidationService{public void validatePayable(Bill b){if(b.getFinalAmount()==null||b.getFinalAmount().compareTo(BigDecimal.ZERO)<0)throw new BusinessRuleException("Invalid bill amount");if("SUCCESS".equalsIgnoreCase(b.getPaymentStatus()))throw new BusinessRuleException("Bill already paid");}}
